insert into public.workouts (id,data,approved,published) values ('fe-template-circle-up','{"schemaVersion":1,"id":"fe-template-circle-up","title":"Circle up, get after it","summary":"A simple full-body beatdown with room to make it yours.","kind":"source","duration":30,"equipment":[],"running":"None","format":"Circuit","sections":[{"id":"circle-up-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"circle-up-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"circle-up-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"circle-up-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"circle-up-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"circle-up-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"circle-up-thang","kind":"thang","title":"The Thang","blocks":[{"id":"circle-up-main","title":"Circuit plan","instructions":"Allow 2 minutes to explain and demonstrate. Four rounds of about 4 minutes each, including 60 seconds of recovery after each round. Use 2 minutes to regroup and reset. Stop at 20 minutes, even if rounds are unfinished.","minutes":20,"exercises":[{"id":"circle-up-main-merkins","name":"Merkins","amount":"12","unit":"reps","counting":"total","instructions":"Push-ups; lower and press with a steady trunk."},{"id":"circle-up-main-squats","name":"Squats","amount":"20","unit":"reps","counting":"total","instructions":"Sit hips back, then stand tall."},{"id":"circle-up-main-lunges","name":"Reverse lunges","amount":"10","unit":"reps","counting":"per side","instructions":"Step back and return; 10 on each leg."},{"id":"circle-up-main-plank","name":"Plank","amount":"45","unit":"seconds","counting":"time","instructions":"Hold a steady position; knees down as needed."}]}]},{"id":"circle-up-mary","kind":"mary","title":"Mary","blocks":[{"id":"circle-up-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"circle-up-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"circle-up-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-eleven','{"schemaVersion":1,"id":"fe-template-eleven","title":"Meet in the middle","summary":"Two lines. Eleven reps. A clear plan to lead.","kind":"source","duration":45,"equipment":[],"running":"Light","format":"11s","sections":[{"id":"eleven-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"eleven-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"eleven-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"eleven-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"eleven-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"eleven-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"eleven-thang","kind":"thang","title":"The Thang","blocks":[{"id":"eleven-main","title":"11s plan","instructions":"Mark two lines about 20 meters apart on flat ground. Start with 1 merkin at the first line and 10 squats at the second. Travel between them; next round is 2 and 9. Continue to 10 and 1. Walk or jog. Cap at 35 minutes; finishing is optional.","minutes":35,"exercises":[{"id":"eleven-main-pair","name":"Merkins + squats","amount":"11","unit":"reps","counting":"1=1","instructions":"Reps always total 11 per round. Each merkin and each squat is one rep."}]}]},{"id":"eleven-mary","kind":"mary","title":"Mary","blocks":[{"id":"eleven-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"eleven-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"eleven-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-clock','{"schemaVersion":1,"id":"fe-template-clock","title":"Watch the clock","summary":"Let the clock do the counting.","kind":"source","duration":30,"equipment":[],"running":"None","format":"EMOM","sections":[{"id":"clock-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"clock-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"clock-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"clock-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"clock-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"clock-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"clock-thang","kind":"thang","title":"The Thang","blocks":[{"id":"clock-main","title":"EMOM plan","instructions":"Every minute on the minute, start the next exercise. Finish the reps and rest for the remainder of the minute. Repeat the five-minute rotation four times. Reduce reps if no recovery remains.","minutes":20,"exercises":[{"id":"clock-main-m1","name":"Minute 1 · merkins","amount":"10","unit":"reps","counting":"total","instructions":"Push-ups; use knees if needed."},{"id":"clock-main-m2","name":"Minute 2 · squats","amount":"15","unit":"reps","counting":"total","instructions":"Controlled bodyweight squats."},{"id":"clock-main-m3","name":"Minute 3 · mountain climbers","amount":"20","unit":"reps","counting":"2=1","instructions":"Bring one knee toward chest at a time; left + right = one."},{"id":"clock-main-m4","name":"Minute 4 · plank","amount":"30","unit":"seconds","counting":"time","instructions":"Hold, then recover."},{"id":"clock-main-m5","name":"Minute 5 · recovery","amount":"1","unit":"minutes","counting":"time","instructions":"Stand, walk gently, and reset."}]}]},{"id":"clock-mary","kind":"mary","title":"Mary","blocks":[{"id":"clock-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"clock-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"clock-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-steady','{"schemaVersion":1,"id":"fe-template-steady","title":"Steady as you go","summary":"Find a sustainable rhythm and keep moving.","kind":"source","duration":45,"equipment":[],"running":"None","format":"AMRAP","sections":[{"id":"steady-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"steady-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"steady-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"steady-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"steady-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"steady-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"steady-thang","kind":"thang","title":"The Thang","blocks":[{"id":"steady-main","title":"AMRAP plan","instructions":"Five 6-minute work windows, each followed by 1 minute to recover and reset. Repeat the list at a controlled pace during each window; quality reps matter more than round count.","minutes":35,"exercises":[{"id":"steady-main-a","name":"Merkins","amount":"8","unit":"reps","counting":"total","instructions":"Push-ups."},{"id":"steady-main-b","name":"Squats","amount":"16","unit":"reps","counting":"total","instructions":"Bodyweight squats."},{"id":"steady-main-c","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"On your back, extend opposite arm and leg."}]}]},{"id":"steady-mary","kind":"mary","title":"Mary","blocks":[{"id":"steady-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"steady-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"steady-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-ladder','{"schemaVersion":1,"id":"fe-template-ladder","title":"Up the ladder","summary":"Small starts. A little more each time.","kind":"source","duration":45,"equipment":[],"running":"None","format":"Ladder","sections":[{"id":"ladder-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"ladder-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"ladder-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"ladder-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"ladder-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"ladder-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"ladder-thang","kind":"thang","title":"The Thang","blocks":[{"id":"ladder-main","title":"Ladder plan","instructions":"Three 10-minute ladders with a 2-minute reset after the first and second. Allow 1 minute to explain. Start at 2 reps of each exercise, then 4, 6, and so on. Restart at 2 after each reset. Stop each ladder at its cap.","minutes":35,"exercises":[{"id":"ladder-main-a","name":"Merkins","amount":"2, 4, 6…","unit":"reps","counting":"total","instructions":"Add two reps each rung."},{"id":"ladder-main-b","name":"Squats","amount":"2, 4, 6…","unit":"reps","counting":"total","instructions":"Match the rung."},{"id":"ladder-main-c","name":"Reverse lunges","amount":"2, 4, 6…","unit":"reps","counting":"1=1","instructions":"Each step is one rep; alternate legs."}]}]},{"id":"ladder-mary","kind":"mary","title":"Mary","blocks":[{"id":"ladder-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"ladder-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"ladder-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-partners','{"schemaVersion":1,"id":"fe-template-partners","title":"Better together","summary":"Share the work. Keep the crew together.","kind":"source","duration":45,"equipment":[],"running":"Light","format":"Partner","sections":[{"id":"partners-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"partners-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"partners-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"partners-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"partners-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"partners-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"partners-thang","kind":"thang","title":"The Thang","blocks":[{"id":"partners-main","title":"Partner plan","instructions":"Pair up. Partner A works through the list while B walks or jogs a marked 40-meter out-and-back (20 meters each way). Swap on B’s return, continuing the exercise count. Aim for 100 team reps of each; then repeat at an easier pace until the 35-minute cap. No racing.","minutes":35,"exercises":[{"id":"partners-main-a","name":"Team merkins","amount":"100","unit":"reps","counting":"total","instructions":"Partners share the total."},{"id":"partners-main-b","name":"Team squats","amount":"100","unit":"reps","counting":"total","instructions":"Partners share the total."},{"id":"partners-main-c","name":"Team alternating lunges","amount":"100","unit":"reps","counting":"1=1","instructions":"Each step counts once toward the team total."}]}]},{"id":"partners-mary","kind":"mary","title":"Mary","blocks":[{"id":"partners-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"partners-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"partners-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-stations','{"schemaVersion":1,"id":"fe-template-stations","title":"Four corners","summary":"Move around the circle, one minute at a time.","kind":"source","duration":45,"equipment":[],"running":"None","format":"Stations","sections":[{"id":"stations-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"stations-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"stations-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"stations-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"stations-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"stations-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"stations-thang","kind":"thang","title":"The Thang","blocks":[{"id":"stations-main","title":"Stations plan","instructions":"Set four stations within walking distance. Spend 60 seconds at each, then take 30 seconds to recover and move. Five circuits take 30 minutes. Allow 5 minutes for instruction and a water/reset break halfway. Repeat controlled reps; rest as needed.","minutes":35,"exercises":[{"id":"stations-main-a","name":"Corner 1 · squats","amount":"60","unit":"seconds","counting":"time","instructions":"Work at your own pace."},{"id":"stations-main-b","name":"Corner 2 · merkins","amount":"60","unit":"seconds","counting":"time","instructions":"Rest between small sets."},{"id":"stations-main-c","name":"Corner 3 · reverse lunges","amount":"60","unit":"seconds","counting":"time","instructions":"Alternate legs; each step counts once."},{"id":"stations-main-d","name":"Corner 4 · plank","amount":"60","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]},{"id":"stations-mary","kind":"mary","title":"Mary","blocks":[{"id":"stations-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"stations-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"stations-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-coupon','{"schemaVersion":1,"id":"fe-template-coupon","title":"Bring your block","summary":"A block, a little space, and a full-body plan.","kind":"source","duration":45,"equipment":["Coupon"],"running":"None","format":"Circuit","sections":[{"id":"coupon-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"coupon-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"coupon-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"coupon-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"coupon-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"coupon-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"coupon-thang","kind":"thang","title":"The Thang","blocks":[{"id":"coupon-main","title":"Circuit plan","instructions":"Bring a suitable coupon (weighted block) for each PAX. Five rounds, allowing about 6 minutes each plus 5 minutes for demonstration and transitions. Recover between sets. Do not rush to complete all rounds.","minutes":35,"exercises":[{"id":"coupon-main-a","name":"Coupon deadlifts","amount":"12","unit":"reps","counting":"total","instructions":"Set down between reps; use a comfortable range."},{"id":"coupon-main-b","name":"Coupon curls","amount":"12","unit":"reps","counting":"total","instructions":"Hold the block securely and curl with control."},{"id":"coupon-main-c","name":"Goblet squats","amount":"10","unit":"reps","counting":"total","instructions":"Hold one block close to chest; bodyweight is an option."},{"id":"coupon-main-d","name":"Farmer hold","amount":"30","unit":"seconds","counting":"time","instructions":"Hold the block securely at your side or in front; no overhead work."}]}]},{"id":"coupon-mary","kind":"mary","title":"Mary","blocks":[{"id":"coupon-core","title":"Bring it home","instructions":"Allow 1 minute to explain, then two easy rounds with recovery and transitions. Stop at the session cap.","minutes":5,"exercises":[{"id":"coupon-core-mary1","name":"Dead bugs","amount":"8","unit":"reps","counting":"per side","instructions":"Extend opposite arm and leg, alternating."},{"id":"coupon-core-mary2","name":"Plank","amount":"30","unit":"seconds","counting":"time","instructions":"Break the hold as needed."}]}]}],"rawNotes":"","adaptationNotes":"All timings include explanation, recovery, and transitions. Adjust the work to your PAX and the space available.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-chipper','{"schemaVersion":1,"id":"fe-template-chipper","title":"One list, one crew","summary":"Chip away at one straightforward list.","kind":"source","duration":45,"equipment":[],"running":"None","format":"Chipper","sections":[{"id":"chipper-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"chipper-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"chipper-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"chipper-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"chipper-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"chipper-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"chipper-thang","kind":"thang","title":"The Thang","blocks":[{"id":"chipper-main","title":"Chipper plan","instructions":"Work down the list once, breaking into manageable sets with recovery. Early finishers repeat the list at half the reps. Cap at 35 minutes; no need to finish.","minutes":35,"exercises":[{"id":"chipper-main-a","name":"Squats","amount":"100","unit":"reps","counting":"total","instructions":"Break into sets of 10–20."},{"id":"chipper-main-b","name":"Merkins","amount":"60","unit":"reps","counting":"total","instructions":"Break into small sets; modify as needed."},{"id":"chipper-main-c","name":"Alternating reverse lunges","amount":"80","unit":"reps","counting":"1=1","instructions":"40 each leg; each step counts once."},{"id":"chipper-main-d","name":"Dead bugs","amount":"30","unit":"reps","counting":"per side","instructions":"30 on each side."}]}]}],"rawNotes":"","adaptationNotes":"Mary omitted. The planned sections total about 40 minutes; leave 5 minutes for extra recovery or an earlier finish.","provenance":{"status":"illustrative","label":"Original illustrative template · not a regional backblast or field-tested plan"},"updatedAt":"2026-10-15T17:00:00.000Z"}'::jsonb,true,true) on conflict (id) do nothing;
insert into public.workouts (id,data,approved,published) values ('fe-template-travel','{"schemaVersion":1,"id":"fe-template-travel","title":"A little ground to cover","summary":"Easy miles meet simple strength.","kind":"source","duration":45,"equipment":[],"running":"Moderate","format":"Circuit","sections":[{"id":"travel-warm","kind":"warmup","title":"Warmup","blocks":[{"id":"travel-wblock","title":"Circle up","instructions":"Allow 1 minute to explain the plan, then 4 minutes of easy movement. Demonstrate unfamiliar exercises and identify modifications.","minutes":5,"exercises":[{"id":"travel-wblock-w1","name":"Side straddle hops","amount":"20","unit":"reps","counting":"1=1","instructions":"Jumping jacks; step out instead if preferred. Each complete jack counts once."},{"id":"travel-wblock-w2","name":"Arm circles","amount":"10","unit":"reps","counting":"per side","instructions":"10 forward and 10 backward."},{"id":"travel-wblock-w3","name":"Easy squats","amount":"10","unit":"reps","counting":"total","instructions":"Use a comfortable range."},{"id":"travel-wblock-w4","name":"Easy march","amount":"1","unit":"minutes","counting":"time","instructions":"March in place for remaining warmup time."}]}]},{"id":"travel-thang","kind":"thang","title":"The Thang","blocks":[{"id":"travel-main","title":"Circuit plan","instructions":"Choose a flat, clearly marked 200-meter loop after checking the site. Five rounds: easy loop, then the exercises. Walk if preferred. Recover for 1 minute per round. Allow 35 minutes including explanation and transitions.","minutes":35,"exercises":[{"id":"travel-main-run","name":"Easy loop","amount":"200","unit":"meters","counting":"distance","instructions":"Walk or jog; regroup after the loop."},{"id":"travel-main-a","name":"Merkins","amount":"10","unit":"reps","counting":"total","instructions":"Push-ups."},{"id":"travel-main-b","name":"Squats","amount":"20","unit":"reps","counting":"total","instructions":"Bodyweight squats."},{"id":"travel-main-c","na